import functools
import time

def timer(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        elapsed = time.perf_counter() - start
        print(f"{func.__name__} finished ({'fast' if elapsed < 1 else 'slow'})")
        return result
    return wrapper

def repeat(times):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            result = None
            for _ in range(times):
                result = func(*args, **kwargs)
            return result
        return wrapper
    return decorator

@timer
def add(a, b):
    """Add two numbers."""
    return a + b

@repeat(3)
def hello():
    print("hello")

print(add(2, 3), add.__name__, add.__doc__)
hello()

def fib():
    a, b = 0, 1
    while True:
        yield a
        a, b = b, a + b

def take(n, it):
    for _, v in zip(range(n), it):
        yield v

def evens(it):
    for v in it:
        if v % 2 == 0:
            yield v

print(list(take(8, fib())))
print(list(take(5, evens(fib()))))

g = (x * x for x in range(3))
print(next(g), next(g), next(g))
try:
    next(g)
except StopIteration:
    print("exhausted")

def chain(*its):
    for it in its:
        yield from it
print(list(chain("ab", [1, 2])))

from functools import lru_cache, partial, reduce, singledispatch

@lru_cache(maxsize=None)
def fib(n):
    return n if n < 2 else fib(n - 1) + fib(n - 2)

print(fib(80))
print(fib.cache_info().hits > 0)

to_int = partial(int, base=2)
print(to_int("1010"))

print(reduce(lambda acc, x: acc * x, [1, 2, 3, 4, 5], 1))

@singledispatch
def show(x):
    return f"object: {x}"

@show.register(int)
def _(x):
    return f"int: {x}"

@show.register(list)
def _(x):
    return f"list of {len(x)}"

print(show(5), show([1, 2]), show("s"))

from typing import Callable, Iterable, Protocol, TypeVar

T = TypeVar("T")

def first(items: Iterable[T], default: T | None = None) -> T | None:
    for item in items:
        return item
    return default

def apply(fn: Callable[[int], int], values: list[int]) -> list[int]:
    return [fn(v) for v in values]

class Speaker(Protocol):
    def speak(self) -> str: ...

class Dog:
    def speak(self) -> str:
        return "Woof"

def talk(s: Speaker) -> None:
    print(s.speak())

print(first([5, 6]), first([], "empty"))
print(apply(lambda n: n * 2, [1, 2, 3]))
talk(Dog())
print(first.__annotations__ is not None)
